<script>
import BaseComponent from '@primevue/core/basecomponent';
import CompareStyle from 'primevue/compare/style';

export default {
    name: 'BaseCompare',
    extends: BaseComponent,
    props: {
        modelValue: {
            type: Number,
            default: undefined
        },
        min: {
            type: Number,
            default: 0
        },
        max: {
            type: Number,
            default: 100
        },
        step: {
            type: Number,
            default: 1
        },
        orientation: {
            type: String,
            default: 'horizontal'
        },
        slideOnHover: {
            type: Boolean,
            default: false
        },
        disabled: {
            type: Boolean,
            default: false
        },
        readonly: {
            type: Boolean,
            default: false
        },
        invalid: {
            type: Boolean,
            default: false
        },
        tabindex: {
            type: Number,
            default: undefined
        },
        ariaLabel: {
            type: String,
            default: undefined
        },
        ariaLabelledby: {
            type: String,
            default: undefined
        },
        name: {
            type: String,
            default: undefined
        },
        as: {
            type: [String, Object],
            default: 'DIV'
        },
        asChild: {
            type: Boolean,
            default: false
        }
    },
    style: CompareStyle,
    provide() {
        return {
            $pcCompare: this,
            $parentInstance: this
        };
    }
};
</script>
